{
  "missing_information": [
    {
      "category": "Tool Selection Logic",
      "gap": "No criteria are given for how a specific measurement tool is chosen for a given wafer",
      "why_it_matters": "Without knowing the selection logic (e.g., wafer type, lot priority, tool availability), it is impossible to model the routing decision or assess whether it can be automated"
    },
    {
      "category": "Tool-Specific Steps",
      "gap": "The preparation and measurement steps for each tool are not enumerated or described",
      "why_it_matters": "Each tool variant represents a distinct process path; without step-level detail, the workflow cannot be reconstructed or compared for automation potential"
    },
    {
      "category": "Result Recording Method",
      "gap": "It is unclear how the engineer records the measurement result (manual entry, automated data capture, paper log, etc.) and where the result is stored",
      "why_it_matters": "The recording method directly determines automation feasibility and data quality risks"
    },
    {
      "category": "Acceptance Criteria",
      "gap": "No pass/fail thresholds or out-of-specification handling steps are described",
      "why_it_matters": "Without acceptance criteria, it is unknown whether a decision step follows measurement and whether rework or escalation paths exist"
    },
    {
      "category": "Roles and Responsibilities",
      "gap": "Only 'the engineer' is mentioned; it is unclear whether operators, technicians, or automated systems also participate and at which steps",
      "why_it_matters": "Role clarity is required to identify handoff points, potential bottlenecks, and tasks suitable for automation"
    },
    {
      "category": "Workflow Triggers and Handoffs",
      "gap": "The events that initiate the workflow and signal its completion to downstream processes are not defined",
      "why_it_matters": "Without knowing triggers and handoffs, the workflow cannot be integrated into a broader process model or assessed for end-to-end cycle time"
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What criteria or rules determine which measurement tool is assigned to a given wafer, and is that assignment made by a person, a scheduling system, or some other mechanism?",
      "targets": ["Tool Selection Logic"]
    },
    {
      "id": "Q2",
      "question": "For each tool variant, can you list the discrete preparation and measurement steps in the order they are performed, including any calibration or setup actions that must happen before the wafer is measured?",
      "targets": ["Tool-Specific Steps"]
    },
    {
      "id": "Q3",
      "question": "How does the engineer record the measurement result—for example, manual entry into a form or system, automatic capture from the tool, or a paper log—and where is that result stored after recording?",
      "targets": ["Result Recording Method"]
    },
    {
      "id": "Q4",
      "question": "Are there defined acceptance thresholds for the measurement result, and if a result falls outside those thresholds, what happens next in the process?",
      "targets": ["Acceptance Criteria"]
    },
    {
      "id": "Q5",
      "question": "Besides the engineer, which other roles or automated systems are involved in this workflow, and at which specific steps do they act or make decisions?",
      "targets": ["Roles and Responsibilities"]
    },
    {
      "id": "Q6",
      "question": "What event or condition triggers the start of this measurement workflow, and what signal or output marks its completion so that the next downstream process can begin?",
      "targets": ["Workflow Triggers and Handoffs"]
    }
  ]
}
